#ifndef SOUND_DATA_H
#define SOUND_DATA_H
#include <gb/gb.h>
/* generated by tools/make_sound.py: the tunes (bank 7) */
enum { MUS_TITLE, MUS_PLANET, MUS_DUNGEON, MUS_SPACE, MUS_BOSS, MUS_ENDING, MUS_N };
typedef struct { const UINT8 *mel, *bas, *drm; UINT8 tempo, vol; } SndTrack;   /* drm: 0 none, 1 kick, 2 snare, 3 hat */
extern const UINT16 snd_sq[128];   /* MIDI note -> square-channel frequency register */
extern const UINT16 snd_wv[128];   /* MIDI note -> wave-channel frequency register */
extern const SndTrack snd_tracks[MUS_N];
#endif
